import {financialSummary,assetPosition,configSection,today,outstanding,ledgerBalance,CLASSES} from '../core/business.js?v=20261104-v9a';
export function install(ctx){
 function assetsPage(){const assets=ctx.business.assets;ctx.shell(`${ctx.head('Patrimônio da empresa','Bens, equipamentos e depreciação gerencial.')}<div class="toolbar">${ctx.can('assets','create')?'<button class="primary" id="new-asset">Cadastrar bem</button>':''}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Bem / equipamento</th><th>Aquisição</th><th>Custo</th><th>Vida útil</th><th>Depreciação acumulada</th><th>Valor gerencial</th><th></th></tr></thead><tbody>${assets.map(a=>{const p=assetPosition(a);return `<tr><td><strong>${ctx.esc(a.name)}</strong><small>${ctx.esc(a.notes)}${a.active?'':' · inativo'}</small></td><td>${ctx.date(a.acquired_on)}</td><td>${ctx.money(a.cost)}</td><td>${a.life_months} meses</td><td>${ctx.money(p.depreciation)}</td><td>${ctx.money(p.value)}</td><td>${ctx.can('assets','edit')?`<button class="secondary small" data-asset="${a.id}">Editar</button>`:''}</td></tr>`}).join('')}</tbody></table></div>${assets.length?'':ctx.empty('Patrimônio organizado.','Cadastre máquinas, equipamentos e outros bens da empresa.')}</section><p class="note">O cadastro de um bem não registra a compra no caixa. Registre a obrigação em Financeiro → Compras, com classificação Aquisição de ativo. A depreciação é linear, a partir do mês seguinte à aquisição.</p>`);ctx.$('#new-asset')?.addEventListener('click',()=>assetDialog());document.querySelectorAll('[data-asset]').forEach(el=>el.onclick=()=>assetDialog(assets.find(a=>a.id===el.dataset.asset)))}
 function assetDialog(a={}){const d=ctx.modal(a.id?'Editar bem':'Cadastrar bem',`<form><div class="grid2">${ctx.field('Nome do bem','name','text',a.name||'','required maxlength="200"')}${ctx.field('Aquisição','acquired_on','date',a.acquired_on||today(),`required ${a.id?'disabled':''}`)}${ctx.field('Custo de aquisição (R$)','cost','number',a.cost||'','required min="0.01" step="0.01" '+(a.id?'disabled':''))}${ctx.field('Valor residual (R$)','residual','number',a.residual||0,'required min="0" step="0.01" '+(a.id?'disabled':''))}${ctx.field('Vida útil (meses)','life_months','number',a.life_months||configSection(ctx.settings,'finance').default_life_months,'required min="1" max="1200" '+(a.id?'disabled':''))}<label class="check-row"><input type="checkbox" name="active" ${a.active===false?'':'checked'}>Bem ativo</label><label class="field span2">Observações<textarea name="notes" maxlength="5000">${ctx.esc(a.notes)}</textarea></label></div><p class="note">Custo, aquisição e vida útil ficam preservados após o cadastro.</p><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary">Salvar bem</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const fd=new FormData(e.target),data=Object.fromEntries(fd);data.active=fd.has('active');if(!a.id&&Number(data.residual)>Number(data.cost))throw Error('O residual não pode superar o custo.');await ctx.rpc('save_company_asset',{p_id:a.id||null,p_data:data});await ctx.load();d.close();assetsPage()}catch(err){d.querySelector('.error').textContent=err.message;e.submitter.disabled=false}}}
 function reportsPage(){const c=configSection(ctx.settings,'reports'),now=today();ctx.shell(`${ctx.head('Relatórios para decidir melhor.','Acompanhe caixa, resultado, compromissos e patrimônio.')}<section class="panel"><form id="report-filter" class="panelbody"><div class="grid2">${ctx.field('De','from','date',now.slice(0,7)+'-01','required')}${ctx.field('Até','to','date',now,'required')}<label class="field">Relatório<select name="type"><option value="cash">Movimentações e resultado</option><option value="dre">DRE gerencial</option><option value="forecast">Contas a pagar / receber</option><option value="accounts">Posição das contas</option><option value="assets">Patrimônio e depreciação</option><option value="orders">Pedidos e produção</option></select></label><label class="field">Regime<select name="basis"><option value="cash" ${c.basis==='cash'?'selected':''}>Caixa · pagamentos realizados</option><option value="accrual" ${c.basis==='accrual'?'selected':''}>Competência · títulos registrados</option></select></label></div><div class="form-actions"><button class="primary">Atualizar relatório</button>${ctx.can('reports','print')?'<button type="button" class="secondary" id="report-pdf">Imprimir / Salvar PDF</button><button type="button" class="secondary" id="report-csv">Exportar CSV</button>':''}</div><p class="error" role="alert"></p></form></section><article class="report-print panel" id="report-content"></article>`);let exportRows=[],filename='relatorio';
  function draw(){const fd=new FormData(ctx.$('#report-filter')),from=fd.get('from'),to=fd.get('to'),basis=fd.get('basis'),type=fd.get('type');if(from>to)throw Error('A data inicial deve ser anterior à final.');const b=ctx.business,summary=financialSummary(b.entries,b.settlements,from,to,basis);let title='',columns=[],rows=[],metrics='';
   if(type==='cash'){title='Movimentações e resultado';columns=['Data','Descrição','Categoria','Classificação','Entrada','Saída'];rows=summary.rows.map(e=>[ctx.date(e.date),e.description,e.category,CLASSES[e.class],e.kind==='income'?ctx.money(e.value):'',e.kind==='expense'?ctx.money(e.value):'']);metrics=`<div class="report-totals"><span>Entradas <strong>${ctx.money(summary.totals.income)}</strong></span><span>Saídas <strong>${ctx.money(summary.totals.expense)}</strong></span><span>Resultado <strong>${ctx.money(summary.totals.cash_result)}</strong></span></div>`}
   if(type==='dre'){title='DRE gerencial';columns=['Grupo','Valor'];const t=summary.totals;rows=[['Receita operacional',ctx.money(t.revenue)],['Custos de produção',ctx.money(t.cost)],['Despesas operacionais',ctx.money(t.operating)],['Impostos e taxas',ctx.money(t.tax)],['Resultado operacional',ctx.money(t.operating_result)]];metrics='<p class="note">Aportes, retiradas de capital, transferências e aquisições de ativos ficam fora do resultado operacional. Depreciação e demais ajustes contábeis não estão incluídos nesta DRE gerencial.</p>'}
   if(type==='forecast'){title='Contas a pagar e receber · posição atual por vencimento';columns=['Vencimento','Descrição','Tipo','Categoria','Valor original','Saldo atual'];rows=b.entries.filter(e=>!e.voided&&e.due_date>=from&&e.due_date<=to&&outstanding(e,b.settlements)>0).sort((a,z)=>a.due_date.localeCompare(z.due_date)).map(e=>[ctx.date(e.due_date),e.description,e.kind==='income'?'A receber':'A pagar',e.category,ctx.money(e.amount),ctx.money(outstanding(e,b.settlements))])}
   if(type==='accounts'){title='Posição das contas em '+ctx.date(to);columns=['Conta','Data inicial','Saldo de abertura','Saldo registrado na data'];rows=b.accounts.map(a=>[a.name,ctx.date(a.opening_date),ctx.money(a.opening_balance),to<a.opening_date?'Anterior à abertura':ctx.money(ledgerBalance(a,b.entries,b.settlements,to))])}
   if(type==='assets'){title='Patrimônio em '+ctx.date(to);columns=['Bem','Aquisição','Custo','Depreciação acumulada','Valor gerencial'];rows=b.assets.filter(a=>a.active&&a.acquired_on<=to).map(a=>{const p=assetPosition(a,to);return [a.name,ctx.date(a.acquired_on),ctx.money(a.cost),c.include_depreciation?ctx.money(p.depreciation):'Não considerada',ctx.money(c.include_depreciation?p.value:a.cost)]})}
   if(type==='orders'){title='Pedidos emitidos no período · situação atual';columns=['Pedido','Cliente','Emissão','Entrega prevista','Etapa atual','Total'];rows=ctx.quotes.filter(q=>q.created_at.slice(0,10)>=from&&q.created_at.slice(0,10)<=to).map(q=>['#'+q.number,q.client_snapshot.name,ctx.date(q.created_at),q.delivery_date?ctx.date(q.delivery_date):'—',configSection(ctx.settings,'production').stages.find(s=>s.key===q.stage)?.label||q.stage,ctx.money(q.total)])}
   exportRows=[columns,...rows];filename='avelon-'+type+'-'+to;ctx.$('#report-content').innerHTML=`<div class="report-heading">${c.show_logo?`<div class="brand ${ctx.settings.logo?'custom-brand':'document-brand'}"><img src="${ctx.esc(ctx.settings.logo||'logo-document.png')}" alt="Logo Avelon Têxtil"></div>`:''}<div><h2>${ctx.esc(title)}</h2><p>${ctx.esc(ctx.settings.company||'Avelon Têxtil')} · ${ctx.date(from)} a ${ctx.date(to)}<br>Regime: ${basis==='cash'?'Caixa':'Competência'} · Emitido em ${ctx.date(now)}</p></div></div>${metrics}<div class="table-wrap"><table><thead><tr>${columns.map(x=>`<th>${ctx.esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${ctx.esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length?'':'<p class="muted">Nenhum registro neste período.</p>'}${c.show_signature&&ctx.settings.signature?`<div class="document-signature"><img class="${ctx.settings.signature_invert?'invert-signature':''}" src="${ctx.esc(ctx.settings.signature)}" alt="Assinatura"><p>${ctx.esc(ctx.settings.signature_name)}</p></div>`:''}<p class="report-footer">${ctx.esc(c.footer)}</p>`;
  }
  ctx.$('#report-filter').onsubmit=e=>{e.preventDefault();try{draw();ctx.$('#report-filter .error').textContent=''}catch(err){ctx.$('#report-filter .error').textContent=err.message}};ctx.$('#report-pdf')?.addEventListener('click',async()=>{try{await ctx.rpc('authorize_report');document.body.classList.add('printing-report');window.print()}catch(e){ctx.toast(e.message)}finally{document.body.classList.remove('printing-report')}});ctx.$('#report-csv')?.addEventListener('click',async()=>{try{await ctx.rpc('authorize_report');const csv='\uFEFF'+exportRows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){ctx.toast(e.message)}});draw();
 }
 Object.assign(ctx,{assetsPage,reportsPage});
}
